import portfolio from '@/data/portfolio.json';

export interface Project {
  id: string;
  title: string;
  description: string;
  tags: string[];
  url: string;
  imageUrl: string;
  status: string;
}

export interface Experience {
  id: string;
  dateRange: string;
  title: string;
  company: string;
  description: string;
  tags: string[];
}

// The JSON file is generated by `php artisan portfolio:export` in backend/.
// Do not edit it by hand; edit content in the local Filament admin instead.
const projects: Project[] = portfolio.projects;
const experiences: Experience[] = portfolio.experiences;

export function getProjects(): Project[] {
  return projects;
}

export function getExperiences(): Experience[] {
  return experiences;
}
